data=result.match(/DATA = '(.*?)'/)[1];
nonce=result.match(/<script>\s*window.*?=(.*?)\s*<\/script>/)[1];
nonce=eval(nonce);
var N = String(nonce).match(/\d+\w+/);
jlen=N.length;
while(jlen){
